const circle = (radius) => Object.freeze({ kind: "circle", radius });
const square = (side) => Object.freeze({ kind: "square", side });

function area(shape) {
  switch (shape.kind) {
    case "circle": return Math.PI * shape.radius ** 2;
    case "square": return shape.side ** 2;
    default: throw new TypeError(`unknown shape: ${shape.kind}`);
  }
}
